"use client";
// FR-GWEB-05 (api.md "User interface", Document view; reconcile.md "Download with answers"): the "Documents" tab of the Gaps screen, the
// app's document view for answers (there is no document reader in production). Every corpus document, and the clarifications document
// Specflow generates once it has sections ("Generated by Specflow"), with the banner "N answers are not in the source file yet" (a quiet
// "All answers are in the source file" for none), the list of those answers as links to their gap cards, and "Download with answers": a
// plain link to the BFF export (`GET .../documents/{id}/export?answers=1`, a Markdown attachment of the effective text).
import { useEffect, useState } from "react";
import { Button } from "@/components/ui/Button";
import { EmptyState } from "@/components/ui/EmptyState";
import { GlassSurface } from "@/components/ui/GlassSurface";
import { Icon } from "@/components/ui/Icon";
import { Skeleton } from "@/components/ui/Skeleton";
import { Tag } from "@/components/ui/Tag";
import type { AnswerDocument, DocumentAnswer, GapsPort } from "@/lib/domain/gaps";
import { GapLink } from "./GapLink";
import { GapsUnavailable } from "./GapsUnavailable";
import { failureOf, notInSourceText } from "./gaps-logic";

type Load = AnswerDocument[] | "unavailable" | "failed" | null;

const ANSWER_STATUS: Record<DocumentAnswer["status"], string> = {
  active: "In the effective text",
  undecided: "Waiting for a check against the source",
  applied: "Applied",
  pending: "Waiting to be applied",
};

function AnswerRow({
  answer,
  href,
  onOpenGap,
}: Readonly<{ answer: DocumentAnswer; href: (id: string) => string; onOpenGap: (id: string) => void }>) {
  const title = answer.title === "" ? (answer.gapId ?? answer.clrId) : answer.title;
  return (
    <li className="doc-answer body-sm" data-testid="gap-document-answer">
      {answer.gapId === null ? (
        <span>{title}</span>
      ) : (
        <GapLink
          href={href(answer.gapId)}
          onOpen={() => {
            onOpenGap(answer.gapId ?? "");
          }}
          testId="gap-document-answer-link"
        >
          {title}
        </GapLink>
      )}
      <span className="doc-answer__status">{ANSWER_STATUS[answer.status]}</span>
    </li>
  );
}

function DocumentRow({
  doc,
  exportUrl,
  href,
  onOpenGap,
}: Readonly<{ doc: AnswerDocument; exportUrl: string; href: (id: string) => string; onOpenGap: (id: string) => void }>) {
  const banner = notInSourceText(doc.answers.length);
  const name = doc.title === "" ? doc.path : doc.title;
  return (
    <li className="doc-row" data-testid="gap-document" data-document={doc.documentId} data-generated={doc.generated ? "" : undefined}>
      <div className="doc-row__head">
        <Icon name="file-text" size={20} />
        <div className="doc-row__name">
          <h3 className="doc-row__title headline">{name}</h3>
          <p className="doc-row__path body-sm">{doc.path}</p>
        </div>
        {doc.generated ? <Tag tone="info">Generated by Specflow</Tag> : null}
        <a
          className="gdg-btn gdg-btn--glass gdg-btn--sm"
          href={exportUrl}
          download
          data-testid="gap-document-download"
          aria-label={`Download ${name} with answers`}
        >
          Download with answers
        </a>
      </div>
      {banner === null ? (
        <p className="doc-row__quiet body-sm" data-testid="gap-document-count" data-count="0">
          {doc.generated ? "No answers in this document yet" : "All answers are in the source file"}
        </p>
      ) : (
        <>
          <p className="doc-row__banner body-sm" role="note" data-testid="gap-document-count" data-count={doc.answers.length}>
            <Icon name="warning-circle" size={16} />
            <span>{doc.generated ? banner.replace(" not in the source file yet", " in this generated document") : banner}</span>
          </p>
          <ul className="doc-row__answers" aria-label={`Answers of ${name}`} data-testid="gap-document-answers">
            {doc.answers.map((a) => (
              <AnswerRow key={a.clrId} answer={a} href={href} onOpenGap={onOpenGap} />
            ))}
          </ul>
        </>
      )}
    </li>
  );
}

export function DocumentsTab({
  gaps,
  projectId,
  href,
  onOpenGap,
  version,
}: Readonly<{ gaps: GapsPort; projectId: string; href: (id: string) => string; onOpenGap: (id: string) => void; version: number }>) {
  const [data, setData] = useState<Load>(null);
  const [tries, setTries] = useState(0);
  useEffect(() => {
    let alive = true;
    gaps.answerDocuments(projectId).then(
      (docs) => {
        if (alive) setData(docs);
      },
      (e: unknown) => {
        if (alive) setData(failureOf(e));
      },
    );
    return () => {
      alive = false;
    };
  }, [gaps, projectId, tries, version]);
  if (data === null) return <Skeleton variant="block" height={200} />;
  if (data === "unavailable") return <GapsUnavailable />;
  if (data === "failed") {
    return (
      <EmptyState
        title="The documents could not be loaded"
        icon="warning-circle"
        actions={
          <Button
            onClick={() => {
              setTries((n) => n + 1);
            }}
          >
            Try again
          </Button>
        }
      >
        Check your connection and try again.
      </EmptyState>
    );
  }
  if (data.length === 0) {
    return (
      <div data-testid="gap-documents-empty">
        <EmptyState title="No documents yet" icon="file-text">
          Documents appear here once a build has read them.
        </EmptyState>
      </div>
    );
  }
  return (
    <div className="gap-docs">
      <p className="gaps-count body-sm">
        Answers are applied to the text Specflow reads, not to your files. Download a document with its answers to copy them into your
        source file.
      </p>
      <GlassSurface variant="strong" className="noise">
        <ul className="noise__list" aria-label="Documents" data-testid="gap-documents">
          {data.map((d) => (
            <DocumentRow key={d.documentId} doc={d} exportUrl={gaps.exportUrl(projectId, d.documentId)} href={href} onOpenGap={onOpenGap} />
          ))}
        </ul>
      </GlassSurface>
    </div>
  );
}
